mapper.select:
WITH RECURSIVE org_tree AS ( -- 1. 起始节点（根节点） SELECT id, pid, name, name::TEXT AS path FROM spectra_core.sys_department WHERE pid IS NULL
UNION ALL
-- 2. 递归子节点 SELECT o.id, o.pid, o.name, ot.path || '/' || o.name AS path FROM spectra_core.sys_department o JOIN org_tree ot ON o.pid = ot.id) SELECT path, id FROM org_tree WHERE id = #{id};

mapper.update:
UPDATE spectra_core.sys_department SET pid = #{targetParentId}, updated_by = #{operatorId}, updated_at = CURRENT_TIMESTAMP, version = version + 1 WHERE deleted IS NULL AND id IN
#{childId}
AND pid IN
#{sourceParentId}
